package com.bank.batch;

import java.math.BigDecimal;
import java.util.logging.*;

public class OverloadedMainDemo {
    private static final Logger log = Logger.getLogger("BankLog");
    static {
        Handler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
        log.setLevel(Level.ALL);
    }

    // THE entry point — the ONLY signature the JVM uses to start the app.
    public static void main(String[] args) {
        log.info("JVM entry point: public static void main(String[]) invoked by the launcher.");
        String accountId = args.length > 0 ? args[0] : "SAV2001";
        BigDecimal amount = args.length > 1 ? new BigDecimal(args[1]) : new BigDecimal("50000.00");

        // Delegate to a strongly typed OVERLOAD — just a normal method named main.
        main(accountId, amount);
    }

    // OVERLOAD #1: typed worker. NOT used by the JVM at startup; called explicitly above.
    public static void main(String accountId, BigDecimal amount) {
        log.info(() -> "Overload main(String, BigDecimal): settling Rs." + amount
                        + " for " + accountId);
        // ... real settlement logic (testable directly, no String[] needed)
    }

    // OVERLOAD #2: harmless extra overload — legal, but JVM ignores it at startup.
    public static void main(int runCode) {
        log.info(() -> "Overload main(int): internal run code " + runCode + " (not an entry point)");
    }

    // NOTE: a method named main that returns int is a legal overload but NOT a valid entry point.
    public static int main(boolean dryRun) {
        log.info(() -> "Overload main(boolean) returning int: dryRun=" + dryRun);
        return dryRun ? 0 : 1;
    }
}
